#![no_std]
use soroban_sdk::{contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env};

/// Ledgers before expiry at which a storage entry is extended, and how far it is extended to.
const LIFETIME_THRESHOLD: u32 = 518_400;
const LIFETIME_BUMP: u32 = 1_000_000;

#[contracttype]
pub enum DataKey {
    /// The Stellar Asset Contract that is staked (XLM by default).
    Token,
    /// Total amount staked by all users.
    Total,
    /// Amount staked by one user.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

fn token_client(env: &Env) -> token::Client<'_> {
    let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
    token::Client::new(env, &token)
}

fn check_amount(env: &Env, amount: i128) {
    if amount <= 0 {
        panic_with_error!(env, Error::InvalidAmount);
    }
}

fn read_staked(env: &Env, user: &Address) -> i128 {
    let key = DataKey::Staked(user.clone());
    match env.storage().persistent().get::<_, i128>(&key) {
        Some(amount) => {
            env.storage()
                .persistent()
                .extend_ttl(&key, LIFETIME_THRESHOLD, LIFETIME_BUMP);
            amount
        }
        None => 0,
    }
}

fn write_staked(env: &Env, user: &Address, amount: i128) {
    let key = DataKey::Staked(user.clone());
    env.storage().persistent().set(&key, &amount);
    env.storage()
        .persistent()
        .extend_ttl(&key, LIFETIME_THRESHOLD, LIFETIME_BUMP);
}

fn read_total(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn write_total(env: &Env, total: i128) {
    env.storage().instance().set(&DataKey::Total, &total);
    env.storage()
        .instance()
        .extend_ttl(LIFETIME_THRESHOLD, LIFETIME_BUMP);
}

#[contractimpl]
impl Staking {
    /// Sets the staked token at deploy time, so the contract is usable right away.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        write_total(&env, 0);
    }

    /// Moves `amount` from `user` into the contract and credits it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        check_amount(&env, amount);

        token_client(&env).transfer(&user, &env.current_contract_address(), &amount);

        write_staked(&env, &user, read_staked(&env, &user) + amount);
        write_total(&env, read_total(&env) + amount);
    }

    /// Returns `amount` from the contract to `user`. Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        check_amount(&env, amount);

        let staked = read_staked(&env, &user);
        if staked < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        write_staked(&env, &user, staked - amount);
        write_total(&env, read_total(&env) - amount);

        token_client(&env).transfer(&env.current_contract_address(), &user, &amount);
    }

    /// Amount that `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        read_staked(&env, &user)
    }

    /// Amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        read_total(&env)
    }
}

