#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, Address, Env};

struct Setup<'a> {
    env: Env,
    client: StakingClient<'a>,
    token: token::Client<'a>,
    contract_id: Address,
}

fn setup<'a>() -> Setup<'a> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token_id.clone(),));
    Setup {
        client: StakingClient::new(&env, &contract_id),
        token: token::Client::new(&env, &token_id),
        contract_id,
        env,
    }
}

fn fund(s: &Setup, user: &Address, amount: i128) {
    let minter = StellarAssetClient::new(&s.env, &s.token.address);
    minter.mint(user, &amount);
}

#[test]
fn stake_records_amount_and_moves_tokens() {
    let s = setup();
    let user = Address::generate(&s.env);
    fund(&s, &user, 1_000);

    s.client.stake(&user, &600);

    assert_eq!(s.client.staked(&user), 600);
    assert_eq!(s.client.total_staked(), 600);
    assert_eq!(s.token.balance(&user), 400);
    assert_eq!(s.token.balance(&s.contract_id), 600);
}

#[test]
fn stake_accumulates_and_total_sums_users() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    fund(&s, &alice, 500);
    fund(&s, &bob, 300);

    s.client.stake(&alice, &200);
    s.client.stake(&alice, &100);
    s.client.stake(&bob, &300);

    assert_eq!(s.client.staked(&alice), 300);
    assert_eq!(s.client.staked(&bob), 300);
    assert_eq!(s.client.total_staked(), 600);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    fund(&s, &user, 1_000);
    s.client.stake(&user, &1_000);

    s.client.unstake(&user, &250);

    assert_eq!(s.client.staked(&user), 750);
    assert_eq!(s.client.total_staked(), 750);
    assert_eq!(s.token.balance(&user), 250);
    assert_eq!(s.token.balance(&s.contract_id), 750);
}

#[test]
fn unstake_everything_leaves_zero() {
    let s = setup();
    let user = Address::generate(&s.env);
    fund(&s, &user, 1_000);
    s.client.stake(&user, &1_000);

    s.client.unstake(&user, &1_000);

    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.token.balance(&user), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let user = Address::generate(&s.env);
    fund(&s, &user, 1_000);
    s.client.stake(&user, &400);

    assert_eq!(
        s.client.try_unstake(&user, &401),
        Err(Ok(Error::InsufficientStake))
    );
    // Nothing changed.
    assert_eq!(s.client.staked(&user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let user = Address::generate(&s.env);

    assert_eq!(
        s.client.try_unstake(&user, &1),
        Err(Ok(Error::InsufficientStake))
    );
}

#[test]
fn stake_and_unstake_reject_non_positive_amounts() {
    let s = setup();
    let user = Address::generate(&s.env);
    fund(&s, &user, 1_000);

    assert_eq!(s.client.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_stake(&user, &-5), Err(Ok(Error::InvalidAmount)));
    s.client.stake(&user, &100);
    assert_eq!(s.client.try_unstake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_unstake(&user, &-1), Err(Ok(Error::InvalidAmount)));
}

#[test]
fn stake_needs_the_user_authorization() {
    let env = Env::default();
    let admin = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token_id,));
    let client = StakingClient::new(&env, &contract_id);
    let user = Address::generate(&env);

    // No authorization was mocked, so the user's require_auth must fail.
    assert!(client.try_stake(&user, &10).is_err());
}

#[test]
fn starts_empty() {
    let s = setup();
    let user = Address::generate(&s.env);
    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
}
