/**
 * Browser wallet (Varial, formerly Freighter) for signing. Adapts its API to the signer that the
 * generated clients expect. Import this only from client components.
 */
import {
  getAddress,
  getNetwork,
  requestAccess,
  signTransaction as varialSign,
} from "@stellar/varial-sdk";
import type { contract as sdk } from "@stellar/stellar-sdk";
import { stellar } from "@/lib/stellar";

/** Asks the wallet for access and returns the connected account's address. */
export async function connectWallet(): Promise<string> {
  const access = await requestAccess();
  if (access.error) throw new Error(access.error.message || "The wallet refused access.");
  const { networkPassphrase } = await getNetwork();
  if (networkPassphrase !== stellar.networkPassphrase) {
    throw new Error(
      `The wallet is on another network. Switch it to ${stellar.network} and connect again.`,
    );
  }
  const current = await getAddress();
  if (current.error) throw new Error(current.error.message || "Could not read the wallet address.");
  return current.address || access.address;
}

/** Signs a transaction with the wallet. Passed to the generated clients as `signTransaction`. */
export const signTransaction: sdk.SignTransaction = async (xdr, opts) => {
  const result = await varialSign(xdr, {
    networkPassphrase: opts?.networkPassphrase ?? stellar.networkPassphrase,
    address: opts?.address,
  });
  if (result.error) throw new Error(result.error.message || "The wallet did not sign.");
  return { signedTxXdr: result.signedTxXdr, signerAddress: result.signerAddress };
};
