import { connection } from "next/server";
import { Suspense } from "react";
import { staking } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";
import { StakeForm } from "./stake-form";

async function readTotal(): Promise<{ total: string } | { error: string }> {
  try {
    const { result } = await staking().total_staked();
    return { total: result.toString() };
  } catch (error) {
    // Some network errors arrive with an empty message; fall back to their text, and say where we called.
    const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
    return { error: `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})` };
  }
}

async function TotalStaked() {
  // Read the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  const outcome = await readTotal();
  if ("error" in outcome) {
    return <span data-testid="total-staked-error">Could not read the contract: {outcome.error}</span>;
  }
  return <span data-testid="total-staked">{outcome.total}</span>;
}

export default function StakingPage() {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <p>
        Total staked (stroops):{" "}
        <Suspense fallback={<span>Reading the contract…</span>}>
          <TotalStaked />
        </Suspense>
      </p>
      <StakeForm />
    </main>
  );
}
