"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { staking } from "@/lib/contracts";
import { connectWallet, signTransaction } from "@/lib/wallet";

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Connects a wallet and stakes an amount (in stroops, 1 XLM = 10,000,000) from that wallet. */
export function StakeForm() {
  const router = useRouter();
  const [address, setAddress] = useState<string>();
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string>();
  const [error, setError] = useState<string>();

  async function connect() {
    setError(undefined);
    try {
      setAddress(await connectWallet());
    } catch (err) {
      setError(describe(err));
    }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);
    setMessage(undefined);
    if (!address) {
      setError("Connect a wallet first.");
      return;
    }
    const text = amount.trim();
    if (!/^[1-9][0-9]*$/.test(text)) {
      setError("Enter a whole number of stroops, greater than zero.");
      return;
    }
    setBusy(true);
    try {
      const client = staking({ publicKey: address, signTransaction });
      const tx = await client.stake({ user: address, amount: BigInt(text) });
      await tx.signAndSend();
      setMessage(`Staked ${text} stroops.`);
      setAmount("");
      router.refresh();
    } catch (err) {
      setError(describe(err));
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <p>
        <button type="button" data-testid="connect-wallet" onClick={connect} disabled={busy}>
          {address ? "Wallet connected" : "Connect wallet"}
        </button>{" "}
        {address && <code data-testid="wallet-address">{address}</code>}
      </p>
      <form onSubmit={submit}>
        <label>
          Amount (stroops){" "}
          <input
            data-testid="stake-amount"
            type="text"
            inputMode="numeric"
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            placeholder="10000000"
            disabled={busy}
          />
        </label>{" "}
        <button type="submit" data-testid="stake-submit" disabled={!address || busy}>
          {busy ? "Staking…" : "Stake"}
        </button>
      </form>
      {message && <p data-testid="stake-message">{message}</p>}
      {error && <p data-testid="stake-error">{error}</p>}
    </section>
  );
}
EOF
